import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

describe('WatchlistStore clearWatched', () => {
  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
  });

  const movie = (id: number, title: string): TmdbMovie => ({
    id,
    title,
    release_date: '2024-01-01',
    poster_path: null,
    overview: 'Overview text.'
  });

  it('removes watched items and keeps unwatched items in order', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'A'));
    store.add(movie(2, 'B'));
    store.add(movie(3, 'C'));
    store.add(movie(4, 'D'));
    store.toggleWatched(2);
    store.toggleWatched(4);

    store.clearWatched();

    expect(store.items().map((m) => m.id)).toEqual([1, 3]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('is a no-op when nothing is watched', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'A'));
    store.add(movie(2, 'B'));

    store.clearWatched();

    expect(store.items().map((m) => m.id)).toEqual([1, 2]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('empties a fully watched list', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'A'));
    store.add(movie(2, 'B'));
    store.toggleWatched(1);
    store.toggleWatched(2);

    store.clearWatched();

    expect(store.items()).toEqual([]);
    expect(store.count()).toBe(0);
    expect(store.watchedCount()).toBe(0);
  });

  it('persists the cleared list for later store instances', () => {
    const store = new WatchlistStore();
    store.add(movie(1, 'A'));
    store.add(movie(2, 'B'));
    store.toggleWatched(1);

    store.clearWatched();

    const reopened = new WatchlistStore();
    expect(reopened.items().map((m) => m.id)).toEqual([2]);
    expect(reopened.watchedCount()).toBe(0);
  });
});

